        ExecutionEntity execution = commandContext.getExecutionEntityManager().findById(job.getProcessInstanceId());
        if (execution != null) {
          commandContext.getExecutionEntityManager().clearProcessInstanceLockTime(execution.getId());
        } 
      }
    }

    return null;
  }

